import{_ as n,l as i,o as t,c as s,v as p,p as E,x as o,d as l,i as c,S as d,b as e}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"小模型代理实验","description":"","frontmatter":{"title":"小模型代理实验","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/proxy-model-experiments.md","filePath":"llm/proxy-model-experiments.md","lastUpdated":1789023840000}'),m={name:"llm/proxy-model-experiments.md"};function h(B,a,A,u,f,x){const r=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=p('<h1 id="小模型代理实验" tabindex="-1">小模型代理实验 <a class="header-anchor" href="#小模型代理实验" aria-label="Permalink to &quot;小模型代理实验&quot;">​</a></h1><div class="epigraph"><p>能在小模型上用大学习率复现的不稳，才配叫机制；只在小模型上降了损失的改动，迁移到大模型时必须再过 coord check 与同一稳定件。</p><footer>—— Wortsman et al., Small-scale proxies for large-scale Transformer training instabilities, ICLR 2024；超参迁移见 Yang 等 μP</footer></div><p><a href="/llm/inference-compute-optimal">上一课</a>把预算决策放到损失面与推理账上。缺口是：你没有预算在目标宽度上扫完所有稳定件与形状。Wortsman 等人说明大模型训练不稳可以在小模型上<strong>故意加 \\(\\eta\\)</strong> 复现，从而把 cap、QK-Norm、\\(\\beta_2\\) 的消融放在代理上。μP 则要求代理与目标同参数化。本课把「代理实验」写成缩放实践的方法，而不是「小模型论文」。后课的生长与升级，默认先在代理上验证拼接是否炸。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代理失败有两种。假阴性：小模型太稳，大学习率不稳在小宽度上不出现，于是你关掉 cap，目标宽度上炸。假阳性：小模型数据制度不同（更多 epoch、更小 \\(U\\)），某正则在代理上有用，目标上是纯伤害。Wortsman 的处方针对不稳：<strong>提高代理 \\(\\eta\\) 直到出现与大模型同类的传感器报警</strong>（熵塌缩、尖峰），再测对策是否把悬崖推走。μP 的处方针对超参：<strong>宽度轴 coord check 平坦</strong> 才迁 \\(\\eta\\)。</p><p>两者都要求：深度、词表、稳定件集合尽量同构，只缩宽度或只缩 \\(N\\)。把 6 层 GELU 代理的结论迁到 80 层 SwiGLU 目标，叫架构消融，不叫代理。</p><p><span class="marginnote">代理的 token 数不应按参数比线性缩到几乎只剩压熵段。阶段课写过：架构差别出现在幂律段。代理至少要看见斜率，而不是只比 1 个 epoch 的终点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计清单：</p><ol><li>同深度带子、同词表或按词表定律缩小后声明不可比的部分。</li><li>同优化器分组、同 \\(\\beta_2/\\varepsilon\\)、同是否 cap。</li><li>不稳代理：扫 \\(\\eta\\) 直到触顶率 / 熵报警，记录悬崖位置；再打开候选稳定件，看悬崖是否右移。</li><li>超参代理：μP infshape + coord check，再迁。</li><li>数据制度：尽量同 \\(R\\)、同配比；否则把差异写进「不可迁」列表。</li></ol><p>验收迁移：目标模型上只跑少量 step 的 coord check 与传感器，不要求跑完。若代理说 cap 右移悬崖、目标上前 2k step 熵仍塌，是实现未对齐（Flash 核无 cap），不是代理理论失败。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不稳往往来自尺度连乘，宽度是放大器。小模型把 \\(\\eta\\) 当放大器，可以进入同一饱和区，这是假宽度上的应力测试。损失面的幂律指数则对绝对 \\(N\\) 敏感，小代理拟合的 \\(\\alpha\\) 外推要留出（拟合课）。所以：稳定件用应力代理；谷底用一组覆盖两三个数量级 \\(N\\) 的真缩放跑，不要用单档 100M 拟合去买 70B。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把代理当缩小版产品评测：涌现课已说明阈值指标在小模型上全是随机。下游只作 sanity，不作 SOTA 决策。下一课开始改<strong>已有检查点的形状</strong>：往深长、往 MoE 长，而不是从随机初始化扫 \\(N\\)。</p>',15)),(t(),E(d,null,{default:o(()=>[c(r,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%E6%9E%B6%E6%9E%84%E5%90%8C%E6%9E%84%22%5D%20--%3E%20ST%5B%22%E5%BA%94%E5%8A%9B%E4%BB%A3%E7%90%86%EF%BC%9A%E5%8A%A0%E5%A4%A7%20eta%20%E5%A4%8D%E7%8E%B0%E4%B8%8D%E7%A8%B3%22%5D%0A%20%20TGT%20--%3E%20MU%5B%22%CE%BCP%20%E4%BB%A3%E7%90%86%EF%BC%9Acoord%20check%22%5D%0A%20%20ST%20--%3E%20FIX%5B%22%E7%A8%B3%E5%AE%9A%E4%BB%B6%E6%98%AF%E5%90%A6%E5%8F%B3%E7%A7%BB%E6%82%AC%E5%B4%96%22%5D%0A%20%20MU%20--%3E%20HP%5B%22%E8%BF%81%E7%A7%BB%20eta%22%5D%0A%20%20FIX%20--%3E%20SPOT%5B%22%E7%9B%AE%E6%A0%87%E4%B8%8A%E7%9F%AD%E8%B7%91%E4%BC%A0%E6%84%9F%E5%99%A8%22%5D%0A%20%20HP%20--%3E%20SPOT%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"不稳用加大 \\(\\eta\\) 的小代理复现；超参用 μP coord check；两者都要求同构稳定件。"),e("li",null,"假阴性来自代理太稳，假阳性来自数据制度不同。"),e("li",null,"代理要跑进幂律段；不要用单档小模型拟合 \\(\\alpha\\) 买大模型。"),e("li",null,"迁移失败先查实现对齐，再查代理设计。"),e("li",null,"出处：Wortsman et al., ICLR 2024；Yang 等，Tensor Programs V。")],-1))])}const _=n(m,[["render",h]]);export{T as __pageData,_ as default};
